(() => {
const views=[...document.querySelectorAll('.view')], topics=[...document.querySelectorAll('.topic')];
const ids=views.map(v=>v.id), menu=document.querySelector('#menu-button'), sidebar=document.querySelector('#sidebar'), veil=document.querySelector('#veil');
const routeIds=['inicio',...topics.map(v=>v.id),'checklist','exercicio','fontes'];
function closeMenu(){document.body.classList.remove('menu-open');menu.setAttribute('aria-expanded','false');veil.hidden=true;sidebar.inert=matchMedia('(max-width:760px)').matches;}
function route(focus=true){let id=decodeURIComponent(location.hash.slice(1))||'inicio';if(!ids.includes(id))id='inicio';views.forEach(v=>v.hidden=v.id!==id);document.querySelectorAll('nav a').forEach(a=>{if(a.hash==='#'+id){a.setAttribute('aria-current','page');const d=a.closest('details');if(d)d.open=true;}else a.removeAttribute('aria-current')});const at=routeIds.indexOf(id), prev=document.querySelector('#prev'),next=document.querySelector('#next');prev.href='#'+(routeIds[Math.max(0,at-1)]||'inicio');next.href='#'+(routeIds[at+1]||'inicio');prev.textContent=at<=1?'← Visão geral':'← Anterior';next.textContent=at===routeIds.length-1?'Voltar ao início ↑':at===0?'Primeiro tema →':'Próximo →';document.querySelector('#position').textContent=topics.some(t=>t.id===id)?`${topics.findIndex(t=>t.id===id)+1} / 37`:'';const h=document.getElementById(id).querySelector('h1');document.title=(id==='inicio'?'Fundamentos de UI mobile':h.textContent+' · UI mobile');closeMenu();window.scrollTo(0,0);if(focus)h.focus({preventScroll:true});}
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';document.body.classList.toggle('menu-open',open);menu.setAttribute('aria-expanded',String(open));veil.hidden=!open;sidebar.inert=!open;if(open)document.querySelector('#search').focus();});veil.addEventListener('click',closeMenu);
window.addEventListener('hashchange',()=>route());window.addEventListener('resize',()=>{sidebar.inert=matchMedia('(max-width:760px)').matches&&!document.body.classList.contains('menu-open')});
document.querySelector('#search').addEventListener('input',e=>{const q=e.target.value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();document.querySelectorAll('.chapter').forEach(d=>{let hits=0;d.querySelectorAll('a').forEach(a=>{const match=a.dataset.search.normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(q);a.hidden=!match;if(match)hits++});d.hidden=!hits;if(q&&hits)d.open=true;});});
const dialog=document.querySelector('#lightbox');document.querySelectorAll('.visual').forEach(b=>b.addEventListener('click',()=>{document.querySelector('#zoom-image').src=b.dataset.image;document.querySelector('#zoom-image').alt=b.dataset.caption;document.querySelector('#zoom-caption').textContent=b.dataset.caption;document.querySelector('#original').href=b.dataset.image;dialog.showModal();document.querySelector('#close-dialog').focus();}));document.querySelector('#close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog&& (e.clientX<dialog.getBoundingClientRect().left||e.clientX>dialog.getBoundingClientRect().right||e.clientY<dialog.getBoundingClientRect().top||e.clientY>dialog.getBoundingClientRect().bottom))dialog.close();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('menu-open')){closeMenu();menu.focus();}if(e.altKey&&!e.ctrlKey&&!e.metaKey&&!dialog.open){if(e.key==='ArrowRight'){e.preventDefault();document.querySelector('#next').click();}if(e.key==='ArrowLeft'){e.preventDefault();document.querySelector('#prev').click();}}if(e.key==='Tab'&&document.body.classList.contains('menu-open')){const els=[menu,...sidebar.querySelectorAll('a[href],input,summary')].filter(el=>el.getClientRects().length);if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0].focus();}}});route(false);
})();
